def heading(k,t,p=''):
 return f'<div class="section-title"><div><p class="eyebrow">{k}</p><h2>{t}</h2></div><p>{p}</p></div>'

def product():
 return '<section class="wrap product-showcase"><div><p class="eyebrow">UN PRODUIT SOFTNEUR · ÉDUCATION</p><h2>DeepAMC</h2><h3>AMC sur Mobile</h3><p>Une solution pour accompagner les enseignants dans la correction de copies et prolonger leur travail avec Auto Multiple Choice.</p><a class="button" href="https://deepamc.app/">Découvrir DeepAMC ↗</a></div><div class="product-steps"><article><b>01</b><div><h3>Numériser</h3><p>Capturer les feuilles de réponses ou importer des documents déjà scannés.</p></div></article><article><b>02</b><div><h3>Vérifier et corriger</h3><p>Examiner les réponses et les ambiguïtés, puis retrouver les copies annotées.</p></div></article><article><b>03</b><div><h3>Échanger avec AMC</h3><p>Préparer les sujets et transférer les résultats avec DeepAMC Desktop.</p></div></article></div></section>'

def approach():
 steps=[('Comprendre','Échanger sur vos besoins et vos contraintes.'),('Concevoir','Définir les parcours et la solution.'),('Développer','Construire et vérifier les fonctionnalités.'),('Déployer','Préparer la mise à disposition.'),('Accompagner','Suivre les usages et les évolutions.'),('Transmettre','Faciliter la prise en main.')]
