 html=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{label} — SoftNeur</title><meta name="description" content="SoftNeur : logiciels, applications, solutions numériques et intelligence artificielle. {label}."><meta name="theme-color" content="#071b4b"><link rel="stylesheet" href="assets/site.css"><link rel="stylesheet" href="assets/multipage.css"><script src="assets/contact.js" defer></script></head><body><a class="skip" href="#contenu">Aller au contenu</a><header class="header wrap"><a href="index.html" aria-label="SoftNeur, accueil"><img class="logo" src="assets/softneur.svg" width="198" height="64" alt="SoftNeur"></a><nav aria-label="Navigation principale">{nav}</nav><a class="button" href="contact.html#message">Nous contacter →</a></header><main id="contenu">{content}</main><section class="wrap closing"><div><p class="eyebrow">DONNONS FORME À VOTRE PROJET</p><h2>Vos idées. Des solutions concrètes.</h2></div><a class="button" href="contact.html#message">Parlons-en →</a></section><footer class="wrap footer"><a href="index.html"><img class="logo" src="assets/softneur.svg" width="160" height="52" alt="SoftNeur"></a><a href="mailto:softneur.wedra@gmail.com">softneur.wedra@gmail.com</a><a href="tel:+22674394847">+226 74 39 48 47</a><p>© SoftNeur · Where Software Meets Intelligence.</p></footer></body></html>'''
 html=html.replace('</head>','<link rel="stylesheet" href="assets/mockup.css"><link rel="stylesheet" href="assets/brand-motifs.css"></head>')
